ALTER TABLE entities ADD CONSTRAINT role_requires_circle CHECK(kind='CIRCLE' OR parent_id IS NOT NULL);
CREATE FUNCTION validate_parent_circle() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM entities WHERE organization_id=NEW.organization_id AND id=NEW.parent_id AND kind='CIRCLE' AND NOT archived) THEN RAISE EXCEPTION 'Invalid parent circle' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER entity_parent BEFORE INSERT OR UPDATE OF parent_id ON entities FOR EACH ROW EXECUTE FUNCTION validate_parent_circle();
CREATE FUNCTION validate_association_kind() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME='circle_memberships' THEN IF NOT EXISTS(SELECT 1 FROM entities WHERE organization_id=NEW.organization_id AND id=NEW.circle_id AND kind='CIRCLE' AND NOT archived) THEN RAISE EXCEPTION 'Invalid circle' USING ERRCODE='23514'; END IF; ELSE IF NOT EXISTS(SELECT 1 FROM entities WHERE organization_id=NEW.organization_id AND id=NEW.role_id AND kind='ROLE' AND NOT archived) THEN RAISE EXCEPTION 'Invalid role' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER circle_association BEFORE INSERT OR UPDATE ON circle_memberships FOR EACH ROW EXECUTE FUNCTION validate_association_kind();
CREATE TRIGGER role_occupation BEFORE INSERT OR UPDATE ON occupancies FOR EACH ROW EXECUTE FUNCTION validate_association_kind();
